\label{Prop-Ou} Let $\phi:M^{m}\hookrightarrow L^m(\varepsilon)\times \mathbb{R}$ be a hypersurface and denote by $H$ its mean curvature function. Then the bitension field $\tau_2(\phi)=\tau_2$ is given by
$$
\tau_2=\left[\tau_2\right]^{\top}+\left[\tau_2\right]^{\perp}
$$
where
\begin{equation}\label{BHP1}
\begin{aligned}
\left[\tau_2\right]^{\top}= & -2 m A( \operatorname{grad} H)-m^2 H \operatorname{grad} H-2 m(m-1) \varepsilon H \cos \alpha\, T 
\end{aligned}
\end{equation}
is the tangential component, while
\begin{equation}\label{BHP2}
\begin{aligned}
\left[\tau_2\right]^{\perp} = &m \big\{-\Delta H-  H |A|^2 + \varepsilon  (m-1) H \sin^2\alpha\big\}\eta 
\end{aligned}
\end{equation}
is the normal component.

\label{Prop-CMC} Let $M^m$ be a {non-minimal} CMC hypersurface in $L^m(\varepsilon)\times{\mathbb R}$.
\begin{itemize}
\item[{\rm (i)}] If $M^m$ is biconservative, then it is a cylinder $M^{m-1}\times{\mathbb R}$, where $M^{m-1}$ is a non-minimal CMC hypersurface in $L^m(\varepsilon)$.
\item[{\rm (ii)}] If $M^m$ is biharmonic, then it is a cylinder $M^{m-1}\times{\mathbb R}$, where $M^{m-1}$ is a non-minimal CMC biharmonic hypersurface in $L^m(\varepsilon)$.
\end{itemize}

\label{Th-constant-angle}
Let $\phi:M^{m}\hookrightarrow L^m(\varepsilon)\times \mathbb{R}$  be a proper biconservative (biharmonic) hypersurface with constant angle $\alpha$. Then, locally, 
$M^{m}$ is a cylinder $M^{m-1}\times {\mathbb R}$ and $\phi(x,t)=(\bar\phi(x),t)$, where $\bar\phi:M^{m-1}\hookrightarrow L^m(\varepsilon)$ is a proper biconservative (biharmonic) hypersurface.

\label{teo:main-tojeiro}
Any map $\phi$ of the Tojeiro family \eqref{eq:phi-tojeiro-family} defines, at regular points, a hypersurface that has $T$ as
a principal direction. Conversely, any hypersurface $\phi: M^m \hookrightarrow L^m(\varepsilon) \times \mathbb{R}$, $m\geq 2$, with $\cos \alpha \neq 0$ everywhere and having T as a principal direction is locally described as in \eqref{eq:phi-tojeiro-family}.

\label{Th-nostro-1}
Let $\phi:M^{m}\hookrightarrow L^m(\varepsilon)\times \mathbb{R}$ be a proper biconservative hypersurface such that $\operatorname{grad} H$ is a principal direction.  
If $\cos\alpha\neq 0$ everywhere, then $M^{m}$ {is locally described as a Tojeiro hypersurface \eqref{eq:phi-tojeiro-family} with $f_0: M^{m-1} \rightarrow L^m(\varepsilon)$ isoparametric.}

\label{Th-non-umbil-bic}
Let $m\ge2$. There exists a complete, non-cylindrical proper biconservative hypersurface
\[
 \phi:{M}^m
       \hookrightarrow \mathbb H^m\times\mathbb R
       \] 
such that 
\begin{itemize}
\item[{\rm (i)}]  $\phi$ is non-totally umbilical and if $m=4$ has constant scalar curvature ${\rm Scal}=-12$;
\item[{\rm (ii)}] The squared mean curvature function $H^2$ of $\phi$ is non-constant and bounded;
\item[{\rm (iii)}] The Ricci curvature of $\phi$ is bounded from below.
\end{itemize}

From the first equation of \eqref{eq-biharm-system-2} we have
\[
H=-\,\frac{m-1}{m} \rho H_s+\frac{1}{m} \rho^{\prime}\,.
\]
Inserting this into the second equation of \eqref{eq-biharm-system-2} we deduce that the condition of biconservativity is equivalent to the following second order ODE for the function $\rho(s)$:
\begin{small}
\begin{equation}\label{eq-bic-rho-ODE}
\rho''=\frac{(m-1) \left(\rho  \rho ' \left(-3 H_s'+(m-1)H_s^2+2 \epsilon \right)-\left((m-1)H_s \rho ^2 \left(2 \varepsilon -H_s'\right)\right)-3 H_s \rho '^2\right)}{(m-1) H_s \rho-3 \rho '}
\end{equation}
\end{small}
Now, we can choose initial conditions
\begin{equation*}\label{eq-init-conditions}
\rho(0)= \rho_0 \quad (0< \rho_0 < 1)\,, \quad \rho'(0)= \rho_1\neq 0
\end{equation*}
in such a way that 
\begin{equation}\label{eq-cond-ex-uniqueness-th-ODE}
(m-1) H_s(0) \rho_0-3 \rho_1 \neq 0\quad{\rm and}\quad (m-1) H_s(0) \rho_0- \rho_1 \neq 0\,.
\end{equation}
With any such choice, the standard existence and uniqueness theorem for the Cauchy problem guarantees that the ODE \eqref{eq-bic-rho-ODE} admits a local solution defined on an open neighbourhood of $s=0$. Of course, there are infinitely many possible choices for which \eqref{eq-cond-ex-uniqueness-th-ODE} is satisfied. Moreover, since $\rho(s)$ is non-constant, the angle function $\alpha$ is also non-constant and so the proof is ended. 

For the sake of completeness, we observe that, using \eqref{eq:rho-def}, we can rewrite the ODE \eqref{eq-bic-rho-ODE} as a third order ODE for the function $a(s)$. In this case, conditions \eqref{eq-cond-ex-uniqueness-th-ODE} become
\begin{align*}
(m-1)H_s(0)\left (a'^3(0) +a'(0) \right )-3 a''(0)\neq 0\quad {\rm and}\\
(m-1)H_s(0)\left (a'^3(0) +a'(0) \right )-a''(0)\neq 0 \,.
\end{align*}

We construct explicitly the required hypersurfaces. We use the upper half-space model
\[
{\mathbb H}^m=\{(x,y):x\in{\mathbb R}^{m-1},\ y>0\}\,,
\qquad
 g_{{\mathbb H}^m}=\frac{dx^2+dy^2}{y^2}\,.
\]
We take the parallel horospheres
\[
f_s(x)=(x,e^s)
\]
which satisfy
\[
\kappa_1(s)=\cdots=\kappa_{m-1}(s)=1\,,
\qquad H_s=1
\]
and consider a Tojeiro hypersurface
\[
\phi(x,s)=\bigl(f_s(x),a(s)\bigr)\,.
\]
According to \eqref{eq-curv-prin}, the principal curvatures of $\phi$ are
\begin{equation}\label{eq:k1kminrho}
k_1^\phi=\cdots=k_{m-1}^\phi=-\rho\,,
\qquad k_m^\phi=\rho'
\end{equation}
and hence its mean curvature is
\begin{equation*}
 H=\frac{1}{m}\big ( \rho'-(m-1)\rho \big )\,.
 \label{eq:mean}
\end{equation*}
In this setting, the biconservative equation reduces to
\begin{equation}
 H'\rho'+\frac m2 HH'-(m-1)H\rho=0\,.
 \label{eq:BC}
\end{equation}
We observe that, according to \eqref{eq:k1kminrho},  if $ \rho(s)=e^{- s}$ the hypersurface is totally umbilical. Therefore, it is natural to seek non-totally umbilical solutions of the type
\begin{equation*}
 \rho(s)=e^{\beta s},\qquad \beta\in {\mathbb R},\;  \beta\neq -1\,,
 \label{eq:rhoexp}
\end{equation*}
which are defined for all $s$ such that $e^{\beta s}<1$.
Then
\begin{equation}\label{eq:r1HH1}
\rho'=\beta\rho\,,
\qquad
H=\frac{\beta-(m-1)}{m}\rho\,,
\qquad
H'=\beta H\,.
\end{equation}
If $\beta=m-1$ the hypersurface is minimal. Since
\[
a'(s)=\frac{\rho(s)}{\sqrt{1-\rho(s)^2}}\,,
\]
we obtain, up to a vertical translation,
\begin{equation*}
 a(s)=\frac1\beta\arcsin\bigl(e^{\beta s}\bigr)\,.
 \label{eq:a}
\end{equation*}
Substituting \eqref{eq:r1HH1} into \eqref{eq:BC} tells us that the biconservativity condition becomes
\begin{equation*}
 3\beta^2-(m-1)\beta-2(m-1)=0
 \label{eq:betaquad}
\end{equation*}
whose solutions are the $\beta_{m\pm}$ defined by
\begin{equation*} \label{eq:betapm}
 \beta_{m\pm}=
 \frac{(m-1)\pm\sqrt{(m-1)(m+23)}}{6}\,.
\end{equation*}
We define
\begin{equation*}\label{eq:beta-choice-intro}
\beta_m=
\begin{cases}
\beta_{2-}=-\dfrac23,&m=2,\\[2mm]
\beta_{m+},&m\ge3.
\end{cases}
\end{equation*}
Now, we set
\begin{equation*}
\phi_m(x,s)=
 \left(
 x,e^s,
 \frac{1}{\beta_m}\arcsin(e^{\beta_m s})
 \right)\,.
 \label{eq:localimm}
\end{equation*}
We conclude that these hypersurfaces are proper biconservative. Moreover, by construction, it is clear that
$\phi_{m}$ has two distinct principal curvatures $k_i^{\phi} $, $i=1,2$, with multiplicities  $(m-1)$ and $1$ respectively. Moreover, according to \eqref{eq:k1kminrho}
\begin{equation*}\label{eq:prop-tra-curv-prin}
k_2^{ \phi}=-\beta_{m}\,k_1^{ \phi}\,.
\end{equation*}

Now, let us focus on completeness.  The induced metric is
\begin{equation*}
 g_{M}=e^{-2s}g_{{\mathbb R}^{m-1}}
 +\frac{ds^2}{1-e^{2\beta_m s}}\,.
 \label{eq:localmetric}
\end{equation*}
The endpoint where $\rho\to1$ lies at finite intrinsic distance. Hence the
$s$-graph itself is not complete. This endpoint is, however, only a vertical
tangent point and so we can extend the hypersurface by reflection. Indeed, let
\[
\lambda=|\beta_{m}|\,.
\]
After possibly reversing the vertical ${\mathbb R}$-coordinate, we introduce a new
parameter $t$ by
\begin{equation*}
 \rho(s)=\sin(\lambda t)\,,
 \qquad
 0<t<\frac{\pi}{\lambda}\,.
 \label{eq:rhot}
\end{equation*}
Since $\rho(s)=e^{\beta_m s}$, we have
\begin{equation}
 s(t)=\frac{1}{\beta_m}
 \log\left({\sin(\lambda t)}\right)\,.
 \label{eq:st}
\end{equation}
Therefore the local graph extends to
\begin{equation*}
 \phi_m(x,t)=
 \left(
 x,
 \sin(\lambda t)^{1/\beta_m}\,,
 t
 \right)\,,
 \qquad
 x\in{\mathbb R}^{m-1},\quad 0<t<\frac{\pi}{\lambda}\,.
 \label{eq:globalimm}
\end{equation*}
The last component is $t$, so the immersion is injective. Moreover, we observe that
\begin{equation*}
 H(t)=\frac{\beta_m-(m-1)}{m}\sin(\lambda t)
 \label{eq:Hglobal}
\end{equation*}
and so property (ii) of the statement of Theorem~\ref{Th-non-umbil-bic} holds. Next, differentiating \eqref{eq:st}, we have
\[
ds=\frac{\lambda}{\beta_m}\cot(\lambda t)dt\,.
\]
Thus
\begin{equation}
 g_{ M}
 =\sin(\lambda t)^{-2/\beta_m}
 g_{{\mathbb R}^{m-1}}
 +\frac{dt^2}{\sin^2(\lambda t)}\,.
 \label{eq:tmetric}
\end{equation}
Next, we introduce the global coordinate
\begin{equation*}
 r=\frac1\lambda\log\tan\frac{\lambda t}{2}\,.
 \label{eq:rcoord}
\end{equation*}
Then $r\in{\mathbb R}$ and
\[
dr=\frac{dt}{\sin(\lambda t)},
\qquad
\sin(\lambda t)=\operatorname{sech}(\lambda r)\,.
\]
Consequently \eqref{eq:tmetric} becomes
\begin{equation}
 g_{ M}
 =f^2(r)\,g_{{\mathbb R}^{m-1}}+dr^2
 \label{eq:rmetric}
\end{equation}
where
\[
f(r)=\cosh(\lambda r)^{1/\beta_m}\,.
\]
Now, since $f(r)$ is a smooth, positive function on the whole ${\mathbb R}$, we easily conclude that these hypersurfaces obtained by reflection of Tojeiro's graphs are complete. 

In summary, to end the proof of Theorem~\ref{Th-non-umbil-bic} it only remains to show that the Ricci curvature of ${M}^m$ is bounded from below and $\operatorname{Scal}=-12$ for $\phi_4$. Indeed, let
\[
E_i= \frac{1}{f}\,\frac{\partial}{\partial x_i}\,, \, i=1,\dots,m-1 \quad {\rm and}\quad E_m=\frac{\partial}{\partial r}\,.
\]
Then $\left \{ E_1, \dots,E_m\right \}$ is a global orthonormal frame field on ${M}^m$ with respect to the induced metric $ g_{ M}$. 
Since $ g_{ M}$ is a warped product metric with flat fiber of dimension $m-1$, one has (see, for example, \cite[p. 209]{MR719023})
\[
\operatorname{Ric}(\partial_r,\partial_r)=-(m-1)\frac{f''}{f}\,,
\]
and, if $1 \le i \le m-1$,
\[
\operatorname{Ric}(E_i,E_i)
=-\frac{f''}{f}
 -(m-2)\left(\frac{f'}f\right)^2\,.
\]
Moreover, all mixed components vanish in this adapted orthonormal frame.
Therefore, using the explicit expression of $f$ in \eqref{eq:rmetric}, we obtain:
\begin{equation*}
 \operatorname{Ric}(\partial_r,\partial_r)
 =-(m-1)\left[1+(\beta_m-1)\operatorname{sech}^2(\lambda r)\right]
 \label{eq:Ricrad}
\end{equation*}
and, for $i=1,\dots,m-1$,
\begin{equation*}
 \operatorname{Ric}(E_i,E_i)
 =-(m-1)+(m-1-\beta_m)\operatorname{sech}^2(\lambda r)\,.
 \label{eq:Rictan}
\end{equation*}
It follows readily that the Ricci curvature of ${M}^m$ is bounded from below. Finally, taking the trace of the Ricci tensor we obtain
\begin{equation*}
 \operatorname{Scal}
 =-m(m-1)
 +(m-1)(m-2\beta_m)\operatorname{sech}^2(\lambda r)\,.
 \label{eq:scalar}
\end{equation*}
Therefore the scalar curvature is constant precisely when
\[
m-2\beta_m=0\,.
\]
More specifically, this occurs only when $m=4$ and $\beta_{4}=2$. In this case we have $\operatorname{Scal}=-12$ and so the proof of Theorem~\ref{Th-non-umbil-bic} is complete.

The method of proof of Theorem~\ref{Th-Max-Principle-application} does not naturally apply to the case of complete biharmonic hypersurfaces in ${\mathbb S}^m \times {\mathbb R}$. Nevertheless, we can prove a related result which requires different, somehow stronger assumptions. More specifically, we have:
{
\begin{proposition}\label{Prop-max-princ-sphere}
Let $\phi:M^{m}\hookrightarrow {\mathbb S}^m \times {\mathbb R}$ be a complete biharmonic hypersurface. Assume that
\[
 |A|^2 \geq m-1 
 \]
 and $H^2$ is of class $L^p$ for some $p>1$.
Then  $\phi:M^{m}\hookrightarrow {\mathbb S}^m \times {\mathbb R}$ is minimal.\end{proposition} 
\begin{proof} Using \eqref{BHP2} and the assumption $|A|^2 \geq m-1$ we have:
\begin{eqnarray*}
\frac{1}{2}\Delta H^2&=&  H \Delta H -  |\operatorname{grad} H|^2 \\
&=&- \big [|A|^2 - (m-1)  \sin^2 \alpha \big ] H^2 -  |\operatorname{grad} H|^2 \leq 0 \,.
\end{eqnarray*}
Now, since $H^2$ is of class $L^p$ for some $p>1$, a classical result of Yau \cite[Theorem 3]{MR417452} (see also \cite{MR662919}) implies that $H$ is constant. Assume that $H\neq 0$, then,  from Proposition~\ref{Prop-CMC} (ii),  $\phi:M^{m}\hookrightarrow {\mathbb S}^m \times {\mathbb R}$ is a cylinder $M^{m-1}\times{\mathbb R}$, where $M^{m-1}$ is a non-minimal CMC biharmonic hypersurface in ${\mathbb S}^m$. Now, in the cylinder $M^{m-1}\times{\mathbb R}$, $H\neq 0$ contradicts that $H^2$ is of class $L^p$ for some $p>1$.
\end{proof}
}






Finally, we point out that, according to the Proposition~4.1 of \cite{MR3107694}, a {\em compact} biharmonic hypersurface in ${\mathbb S}^m\times{\mathbb R}$ is a slice and, by the same argument, we conclude that there exists no compact biharmonic hypersurface in ${\mathbb H}^m\times{\mathbb R}$.

Using \eqref{BHP2} and the assumption $|A|^2 \geq m-1$ we have:
\begin{eqnarray*}
\frac{1}{2}\Delta H^2&=&  H \Delta H -  |\operatorname{grad} H|^2 \\
&=&- \big [|A|^2 - (m-1)  \sin^2 \alpha \big ] H^2 -  |\operatorname{grad} H|^2 \leq 0 \,.
\end{eqnarray*}
Now, since $H^2$ is of class $L^p$ for some $p>1$, a classical result of Yau \cite[Theorem 3]{MR417452} (see also \cite{MR662919}) implies that $H$ is constant. Assume that $H\neq 0$, then,  from Proposition~\ref{Prop-CMC} (ii),  $\phi:M^{m}\hookrightarrow {\mathbb S}^m \times {\mathbb R}$ is a cylinder $M^{m-1}\times{\mathbb R}$, where $M^{m-1}$ is a non-minimal CMC biharmonic hypersurface in ${\mathbb S}^m$. Now, in the cylinder $M^{m-1}\times{\mathbb R}$, $H\neq 0$ contradicts that $H^2$ is of class $L^p$ for some $p>1$.
